<template><div><h1 class="text-3xl font-bold">Articles</h1><p class="mt-2 text-[var(--muted)]">Rédaction manuelle et contenus reçus par l’API.</p><div class="mt-8 grid gap-7 xl:grid-cols-[.9fr_1.1fr]"><form class="card space-y-4" @submit.prevent="create"><h2 class="text-xl font-bold">Nouvel article</h2><input v-model="form.title" class="field" placeholder="Titre" required/><input v-model="form.category" class="field" placeholder="Catégorie" required/><textarea v-model="form.excerpt" class="field min-h-24 py-3" placeholder="Extrait" required/><textarea v-model="form.body" class="field min-h-56 py-3 font-mono text-xs" placeholder="Corps en Markdown" required/><select v-model="form.status" class="field"><option value="draft">Brouillon</option><option value="published">Publié</option></select><button class="btn-primary w-full">Enregistrer</button></form><div class="space-y-3"><article v-for="item in data?.items" :key="item._id" class="card"><div class="flex gap-4"><div class="flex-1"><span class="font-mono text-[10px] uppercase text-violet-700">{{ item.category }} · {{ item.status }}</span><h2 class="mt-2 text-lg font-bold">{{ item.title }}</h2><p class="mt-2 text-xs text-[var(--muted)]">{{ item.source }} · {{ item.readingTime }} min</p></div><div class="flex flex-col gap-2"><button class="rounded-lg border px-3 py-2 text-xs font-bold" @click="toggle(item)">{{ item.status==='published'?'Brouillon':'Publier' }}</button><button class="rounded-lg bg-red-500/10 px-3 py-2 text-xs font-bold text-red-700" @click="remove(item._id)">Supprimer</button></div></div></article></div></div></div></template>
<script setup lang="ts">definePageMeta({middleware:'admin',layout:'admin'});useSeoMeta({title:'Articles',robots:'noindex,nofollow'});const {data,refresh}=await useFetch<any>('/api/admin/articles');const form=reactive({title:'',category:'Stratégie',excerpt:'',body:'',status:'draft'});async function create(){await $fetch('/api/admin/articles',{method:'POST',body:form});Object.assign(form,{title:'',category:'Stratégie',excerpt:'',body:'',status:'draft'});await refresh()}async function toggle(i:any){await $fetch(`/api/admin/articles/${i._id}`,{method:'PATCH',body:{status:i.status==='published'?'draft':'published'}});await refresh()}async function remove(id:string){if(confirm('Supprimer cet article ?')){await $fetch(`/api/admin/articles/${id}`,{method:'DELETE'});await refresh()}}</script>
